function Write-SysLog {
    param(
        [string]$Message,
        [ValidateSet('INFO','WARN','ERROR','DEBUG')]
        [string]$Level = 'INFO',
        [string]$LogFile = $LogFilePath
    )
    $ts = Get-Date -Format 'yyyy-MM-dd HH:mm:ss'
    $entry = "[$ts] [$Level] $Message"
    if (-not (Test-Path (Split-Path $LogFile))) {
        New-Item -ItemType Directory -Path (Split-Path $LogFile) -Force | Out-Null
    }
    Add-Content -Path $LogFile -Value $entry -Encoding UTF8
    if ($Level -eq 'ERROR') { Write-Host $entry -ForegroundColor Red }
    elseif ($Level -eq 'WARN') { Write-Host $entry -ForegroundColor Yellow }
    else { Write-Host $entry -ForegroundColor Cyan }
}

function Send-AlertMail {
    param(
        [string]$To,
        [string]$Subject,
        [string]$Body,
        [string]$From = 'noreply@corp.local'
    )
    try {
        Send-MailMessage -SmtpServer $SMTPServer -From $From -To $To `
            -Subject $Subject -Body $Body -Encoding UTF8 -ErrorAction Stop
        Write-SysLog "Mail envoyé à $To : $Subject"
        return $true
    } catch {
        Write-SysLog "Échec envoi mail : $_" -Level 'ERROR'
        return $false
    }
}

function Invoke-MaintenanceMode {
    param([string]$ComputerName, [switch]$Enable, [string[]]$ServicesToStop, [string[]]$ScheduledTasksToDisable)
    $report = @()
    if ($Enable) {
        foreach ($svc in $ServicesToStop) {
            Stop-Service -Name $svc -ComputerName $ComputerName -Force -ErrorAction SilentlyContinue
            $report += [PSCustomObject]@{ Action='StopService'; Target=$svc; Status='OK' }
        }
        foreach ($task in $ScheduledTasksToDisable) {
            Disable-ScheduledTask -TaskName $task -ComputerName $ComputerName -ErrorAction SilentlyContinue
            $report += [PSCustomObject]@{ Action='DisableTask'; Target=$task; Status='OK' }
        }
        Write-SysLog "Maintenance mode ENABLED on $ComputerName" -Level 'WARN'
    } else {
        foreach ($svc in $ServicesToStop) {
            Start-Service -Name $svc -ComputerName $ComputerName -ErrorAction SilentlyContinue
            $report += [PSCustomObject]@{ Action='StartService'; Target=$svc; Status='OK' }
        }
        foreach ($task in $ScheduledTasksToDisable) {
            Enable-ScheduledTask -TaskName $task -ComputerName $ComputerName -ErrorAction SilentlyContinue
            $report += [PSCustomObject]@{ Action='EnableTask'; Target=$task; Status='OK' }
        }
        Write-SysLog "Maintenance mode DISABLED on $ComputerName" -Level 'INFO'
    }
    return $report
}

function Get-FileIntegrity {
    param([string]$FilePath, [ValidateSet('MD5','SHA1','SHA256')][string]$Algorithm = 'SHA256', [string]$ExpectedHash = '')
    if (-not (Test-Path $FilePath)) { throw "File not found: $FilePath" }
    $hash = Get-FileHash -Path $FilePath -Algorithm $Algorithm
    $matches = if ($ExpectedHash) { $hash.Hash -eq $ExpectedHash.ToUpper() } else { $null }
    $file = Get-Item $FilePath
    return [PSCustomObject]@{
        Hash = $hash.Hash
        Algorithm = $Algorithm
        Matches = $matches
        FileSize = $file.Length
        LastModified = $file.LastWriteTime
        Path = $FilePath
    }
}

function Backup-Rotate {
    param([string]$Directory, [string]$Pattern = '*.bak', [int]$RetentionDays = 30, [switch]$WhatIf)
    $cutoff = (Get-Date).AddDays(-$RetentionDays)
    $oldFiles = Get-ChildItem -Path $Directory -Filter $Pattern -File | Where-Object { $_.LastWriteTime -lt $cutoff }
    $freed = 0
    foreach ($f in $oldFiles) {
        $freed += $f.Length
        if (-not $WhatIf) { Remove-Item -Path $f.FullName -Force -ErrorAction SilentlyContinue }
    }
    Write-SysLog "Backup rotation: $($oldFiles.Count) files deleted, freed $([math]::Round($freed/1MB,2)) MB" -Level 'INFO'
    return [PSCustomObject]@{
        DeletedCount = $oldFiles.Count
        FreedBytes = $freed
        Files = $oldFiles.Name
        RetentionDays = $RetentionDays
        WhatIf = $WhatIf.IsPresent
    }
}

function New-ADUserDSI {
    param(
        [string]$GivenName,
        [string]$Surname,
        [string]$Department,
        [string]$OU = $DefaultOUUsers,
        [string[]]$BaseGroups = @('GRP_Utilisateurs'),
        [string]$TempPassword = 'P@ss_Temp2025!'
    )
    $sam = ($GivenName.Substring(0,1) + $Surname).ToLower() -replace '[^a-z0-9]',''
    $upn = "$sam@$DomainFQDN"
    $secPwd = ConvertTo-SecureString $TempPassword -AsPlainText -Force
    try {
        $user = New-ADUser -GivenName $GivenName -Surname $Surname `
            -Name "$GivenName $Surname" -SamAccountName $sam `
            -UserPrincipalName $upn -Department $Department `
            -Path $OU -AccountPassword $secPwd `
            -ChangePasswordAtLogon $true -Enabled $true -PassThru
        foreach ($grp in $BaseGroups) { Add-ADGroupMember -Identity $grp -Members $sam -ErrorAction SilentlyContinue }
        Write-SysLog "Utilisateur créé : $sam ($upn)" -Level 'INFO'
        return $user
    } catch {
        Write-SysLog "Erreur création utilisateur $sam : $_" -Level 'ERROR'
        throw
    }
}

function Disable-ADUserDSI {
    param(
        [string]$SamAccountName,
        [string]$Reason,
        [string]$ArchiveOU = 'OU=Archives,DC=corp,DC=local'
    )
    try {
        $user = Get-ADUser -Identity $SamAccountName -Properties MemberOf
        Disable-ADAccount -Identity $SamAccountName
        $user.MemberOf | ForEach-Object { Remove-ADGroupMember -Identity $_ -Members $SamAccountName -Confirm:$false -ErrorAction SilentlyContinue }
        Move-ADObject -Identity $user.DistinguishedName -TargetPath $ArchiveOU
        Set-ADUser -Identity $SamAccountName -Description "DESACTIVE $(Get-Date -f yyyy-MM-dd) - $Reason"
        Write-SysLog "Compte désactivé : $SamAccountName | Motif : $Reason" -Level 'WARN'
    } catch {
        Write-SysLog "Erreur désactivation $SamAccountName : $_" -Level 'ERROR'
        throw
    }
}

function Get-ADUserLastLogon {
    param([string]$SamAccountName, [string]$DomainController = $DomainController)
    $dcs = if ($DomainController) { @($DomainController) } else { (Get-ADDomainController -Filter *).Name }
    $lastLogon = $null
    foreach ($dc in $dcs) {
        $user = Get-ADUser -Identity $SamAccountName -Properties LastLogon -Server $dc -ErrorAction SilentlyContinue
        if ($user -and $user.LastLogon) {
            $logon = [datetime]::FromFileTime($user.LastLogon)
            if (-not $lastLogon -or $logon -gt $lastLogon) { $lastLogon = $logon }
        }
    }
    return $lastLogon
}

function Bulk-ADUserCreate {
    param([PSObject[]]$UsersData, [string]$CsvPath = '', [switch]$WhatIf)
    if ($CsvPath -and (Test-Path $CsvPath)) {
        $UsersData = Import-Csv $CsvPath
    }
    $results = @()
    foreach ($u in $UsersData) {
        try {
            if (-not $WhatIf) {
                $user = New-ADUserDSI -GivenName $u.GivenName -Surname $u.Surname -Department $u.Department -OU $u.OU
                $results += [PSCustomObject]@{ SamAccountName=$user.SamAccountName; Status='Created'; Error=$null }
            } else {
                $results += [PSCustomObject]@{ SamAccountName="$($u.GivenName).$($u.Surname)"; Status='WhatIf'; Error=$null }
            }
        } catch {
            $results += [PSCustomObject]@{ SamAccountName="$($u.GivenName).$($u.Surname)"; Status='Failed'; Error=$_.Exception.Message }
        }
    }
    Write-SysLog "Bulk user creation: $($results.Where({$_.Status -eq 'Created'}).Count) created, $($results.Where({$_.Status -eq 'Failed'}).Count) failed"
    return $results
}

function Test-NetworkDiag {
    param([string]$Target, [int]$Port = 443, [string]$DnsServer = '')
    $ping = Test-Connection -ComputerName $Target -Count 4 -Quiet
    $lat  = (Test-Connection -ComputerName $Target -Count 4 | Measure-Object -Property ResponseTime -Average).Average
    $dns  = if ($DnsServer) { Resolve-DnsName $Target -Server $DnsServer -ErrorAction SilentlyContinue }
            else             { Resolve-DnsName $Target -ErrorAction SilentlyContinue }
    $tcpTest = Test-NetConnection -ComputerName $Target -Port $Port -WarningAction SilentlyContinue
    $trace = tracert -d $Target 2>&1
    $report = [PSCustomObject]@{
        Target    = $Target
        Ping      = $ping
        AvgLatencyMs = [math]::Round($lat, 1)
        DNSRecord = $dns.IPAddress -join ', '
        PortOpen  = $tcpTest.TcpTestSucceeded
        Port      = $Port
        TraceRoute = $trace
    }
    Write-SysLog "Diag réseau $Target : Ping=$ping | Latence=${lat}ms | Port $Port=$($tcpTest.TcpTestSucceeded)"
    return $report
}

function Test-PortScan {
    param([string]$Target, [int]$StartPort = 1, [int]$EndPort = 1024, [int]$Timeout = 100, [int]$Threads = 50)
    $openPorts = [System.Collections.Concurrent.ConcurrentBag[int]]::new()
    $range = $StartPort..$EndPort
    $chunks = $range | ForEach-Object -Parallel {
        $tcp = New-Object System.Net.Sockets.TcpClient
        $async = $tcp.BeginConnect($using:Target, $_, $null, $null)
        $wait = $async.AsyncWaitHandle.WaitOne($using:Timeout)
        if ($wait -and $tcp.Connected) {
            $openPorts.Add($_)
            $tcp.EndConnect($async)
        }
        $tcp.Close()
    } -ThrottleLimit $Threads
    $result = $openPorts.ToArray() | Sort-Object
    Write-SysLog "Port scan on $Target: $($result.Count) ports open"
    return $result
}

function Get-GeoIP {
    param([string]$IPAddress = '')
    $url = if ($IPAddress) { "http://ip-api.com/json/$IPAddress" } else { "http://ip-api.com/json" }
    try {
        $data = Invoke-RestMethod -Uri $url -ErrorAction Stop
        return [PSCustomObject]@{
            IP = $data.query
            Country = $data.country
            City = $data.city
            ISP = $data.isp
            Latitude = $data.lat
            Longitude = $data.lon
            Status = $data.status
        }
    } catch {
        Write-SysLog "GeoIP lookup failed: $_" -Level 'ERROR'
        return $null
    }
}

function Get-SystemInventory {
    param([string]$ComputerName = $env:COMPUTERNAME, [switch]$IncludeSoftware)
    $cs   = Get-CimInstance Win32_ComputerSystem  -ComputerName $ComputerName
    $os   = Get-CimInstance Win32_OperatingSystem  -ComputerName $ComputerName
    $cpu  = Get-CimInstance Win32_Processor        -ComputerName $ComputerName
    $bios = Get-CimInstance Win32_BIOS             -ComputerName $ComputerName
    $disk = Get-CimInstance Win32_LogicalDisk       -ComputerName $ComputerName -Filter "DriveType=3"
    $ram  = [math]::Round($cs.TotalPhysicalMemory/1GB, 2)
    $sw   = if ($IncludeSoftware) {
                Get-CimInstance Win32_Product -ComputerName $ComputerName | Select-Object Name, Version, Vendor
            } else { @() }
    [PSCustomObject]@{
        Computer   = $ComputerName
        Model      = "$($cs.Manufacturer) $($cs.Model)"
        SerialNo   = $bios.SerialNumber
        OS         = "$($os.Caption) $($os.Version)"
        CPU        = $cpu.Name
        RAM_GB     = $ram
        Disks      = $disk | Select-Object DeviceID, @{n='Size_GB';e={[math]::Round($_.Size/1GB,1)}}, @{n='Free_GB';e={[math]::Round($_.FreeSpace/1GB,1)}}
        Software   = $sw
        CollectedAt = Get-Date
    }
}

function Get-DiskHealth {
    param([string]$ComputerName = $env:COMPUTERNAME, [int]$ThresholdPct = 15)
    $disks = Get-CimInstance Win32_LogicalDisk -ComputerName $ComputerName -Filter 'DriveType=3'
    foreach ($d in $disks) {
        $total   = [math]::Round($d.Size/1GB, 1)
        $free    = [math]::Round($d.FreeSpace/1GB, 1)
        $pctFree = [math]::Round(($d.FreeSpace/$d.Size)*100, 1)
        $alert   = $pctFree -le $ThresholdPct
        if ($alert) { Write-SysLog "ALERTE espace disque $($d.DeviceID) sur $ComputerName : $pctFree% libre" -Level 'WARN' }
        [PSCustomObject]@{ Computer=$ComputerName; Drive=$d.DeviceID; Total_GB=$total; Free_GB=$free; FreePct=$pctFree; Alert=$alert }
    }
}

function Manage-WindowsService {
    param(
        [string]$ServiceName,
        [ValidateSet('Start','Stop','Restart','SetStartup')][string]$Action,
        [string]$StartupType = 'Automatic',
        [string]$ComputerName = $env:COMPUTERNAME
    )
    switch ($Action) {
        'Start'      { Start-Service   -Name $ServiceName -ComputerName $ComputerName }
        'Stop'       { Stop-Service    -Name $ServiceName -ComputerName $ComputerName -Force }
        'Restart'    { Restart-Service -Name $ServiceName -ComputerName $ComputerName -Force }
        'SetStartup' { Set-Service     -Name $ServiceName -ComputerName $ComputerName -StartupType $StartupType }
    }
    $svc = Get-Service -Name $ServiceName -ComputerName $ComputerName
    Write-SysLog "Service $ServiceName sur $ComputerName : Action=$Action | État=$($svc.Status)"
    return $svc
}

function Get-ServiceHealth {
    param([string[]]$CriticalServices, [string]$ComputerName = $env:COMPUTERNAME, [string]$AlertEmail = '')
    $results = foreach ($svc in $CriticalServices) {
        $s = Get-Service -Name $svc -ComputerName $ComputerName -ErrorAction SilentlyContinue
        $ok = $s -and $s.Status -eq 'Running'
        if (-not $ok) {
            Write-SysLog "SERVICE ARRÊTÉ : $svc sur $ComputerName" -Level 'ERROR'
            if ($AlertEmail) { Send-AlertMail -To $AlertEmail -Subject "[ALERTE] Service $svc arrêté" -Body "Le service $svc sur $ComputerName est arrêté." }
        }
        [PSCustomObject]@{ Computer=$ComputerName; Service=$svc; Status=$s.Status; Healthy=$ok }
    }
    return $results
}

function Get-SecurityEvents {
    param(
        [string]$ComputerName = $DomainController,
        [int[]]$EventIDs = $CriticalEventIDs,
        [int]$HoursBack = 24
    )
    $since  = (Get-Date).AddHours(-$HoursBack)
    $filter = @{ LogName='Security'; Id=$EventIDs; StartTime=$since }
    Get-WinEvent -FilterHashtable $filter -ComputerName $ComputerName -ErrorAction SilentlyContinue | ForEach-Object {
        [PSCustomObject]@{
            TimeCreated = $_.TimeCreated
            EventID     = $_.Id
            Level       = $_.LevelDisplayName
            Message     = $_.Message.Substring(0, [Math]::Min(200, $_.Message.Length))
            Computer    = $_.MachineName
        }
    }
}

function Get-LockedADAccounts {
    param([string]$SearchBase = $DefaultOUUsers)
    $locked = Search-ADAccount -LockedOut -SearchBase $SearchBase -UsersOnly
    foreach ($u in $locked) {
        $lockEvent = Get-WinEvent -FilterHashtable @{LogName='Security'; Id=4740} -ComputerName $DomainController -MaxEvents 100 -ErrorAction SilentlyContinue |
            Where-Object { $_.Properties[0].Value -eq $u.SamAccountName } | Select-Object -First 1
        [PSCustomObject]@{
            SamAccountName = $u.SamAccountName
            Name           = $u.Name
            LockedOutTime  = $u.AccountLockoutTime
            LockSource     = $lockEvent.Properties[1].Value
            LockSourceIP   = $lockEvent.Properties[19].Value
        }
    }
}

function Get-ADComputersList {
    param([string]$SearchBase = $DefaultOUComputers, [switch]$PingCheck, [string]$OSFilter = '*')
    $computers = Get-ADComputer -Filter "OperatingSystem -like '$OSFilter'" -SearchBase $SearchBase `
        -Properties OperatingSystem, OperatingSystemVersion, LastLogonDate, IPv4Address, Description
    foreach ($c in $computers) {
        $online = if ($PingCheck) { Test-Connection -ComputerName $c.Name -Count 1 -Quiet } else { $null }
        [PSCustomObject]@{
            Name        = $c.Name
            OS          = $c.OperatingSystem
            OSVersion   = $c.OperatingSystemVersion
            IP          = $c.IPv4Address
            LastLogon   = $c.LastLogonDate
            Description = $c.Description
            Online      = $online
        }
    }
}

function Export-AuditReport {
    param(
        [PSObject[]]$Data,
        [string]$Title,
        [string]$OutputDir = 'C:\\Reports',
        [string[]]$Format = @('CSV','HTML')
    )
    if (-not (Test-Path $OutputDir)) { New-Item -ItemType Directory $OutputDir -Force | Out-Null }
    $ts    = Get-Date -Format 'yyyyMMdd_HHmmss'
    $base  = Join-Path $OutputDir "${Title}_${ts}"
    $files = @()
    if ('CSV' -in $Format) { $csv = "$base.csv"; $Data | Export-Csv $csv -NoTypeInformation -Encoding UTF8; $files += $csv }
    if ('HTML' -in $Format) {
        $html = "$base.html"
        $rows = $Data | ConvertTo-Html -Title $Title -PreContent "<h2>$Title</h2><p>Généré le $(Get-Date)</p>" `
            -PostContent '<style>body{font-family:Consolas;} table{border-collapse:collapse;} td,th{border:1px solid #333;padding:4px;} tr:nth-child(even){background:#f2f2f2;}</style>'
        $rows | Out-File $html -Encoding UTF8
        $files += $html
    }
    Write-SysLog "Rapport exporté : $($files -join ' | ')"
    return $files
}

function Invoke-CICDPipeline {
    param(
        [string]$PipelineName,
        [string]$Branch = 'main',
        [hashtable]$Variables = @{}
    )
    $headers = @{ 'Authorization' = "Bearer $CI_CD_TOKEN"; 'Content-Type' = 'application/json' }
    $body = @{ definitionName = $PipelineName; sourceBranch = $Branch; variables = $Variables } | ConvertTo-Json -Depth 3
    try {
        $run = Invoke-RestMethod -Uri "$CICD_API_URL/pipelines/run" -Method Post -Headers $headers -Body $body -ErrorAction Stop
        Write-SysLog "Pipeline déclenché : $PipelineName ($($run.runId))"
        return [PSCustomObject]@{ RunId=$run.runId; Status=$run.state; Url=$run.url }
    } catch {
        Write-SysLog "Échec déclenchement pipeline : $_" -Level 'ERROR'
        throw
    }
}

function Get-CloudVMStatus {
    param([ValidateSet('Azure','AWS','GCP')][string]$Provider = 'Azure', [string]$ResourceGroup = '', [hashtable]$TagFilter = @{})
    switch ($Provider) {
        'Azure' {
            if (-not (Get-Module -ListAvailable Az.Compute)) { throw 'Az module required' }
            $vms = if ($ResourceGroup) { Get-AzVM -ResourceGroupName $ResourceGroup } else { Get-AzVM }
            $result = foreach ($vm in $vms) {
                $status = Get-AzVM -ResourceGroupName $vm.ResourceGroupName -Name $vm.Name -Status
                $power = ($status.Statuses | Where-Object Code -like 'PowerState/*').Code -replace 'PowerState/', ''
                [PSCustomObject]@{ Name=$vm.Name; ResourceGroup=$vm.ResourceGroupName; PowerState=$power; Location=$vm.Location; Tags=$vm.Tags }
            }
            return $result
        }
        default { Write-SysLog "Provider $Provider not fully implemented" -Level 'WARN'; return @() }
    }
}

function Send-TeamsAlert {
    param([string]$WebhookUrl, [string]$Title, [string]$Message, [string]$Color = 'FF0000')
    $body = @{
        title = $Title
        text = $Message
        themeColor = $Color
    } | ConvertTo-Json
    try {
        Invoke-RestMethod -Uri $WebhookUrl -Method Post -Body $body -ContentType 'application/json' -ErrorAction Stop
        Write-SysLog "Teams alert sent: $Title"
        return $true
    } catch {
        Write-SysLog "Teams alert failed: $_" -Level 'ERROR'
        return $false
    }
}

function Send-SlackAlert {
    param([string]$WebhookUrl, [string]$Message, [string]$Channel = '#alerts', [string]$Username = 'CodeForge Bot')
    $body = @{ channel = $Channel; username = $Username; text = $Message } | ConvertTo-Json
    try {
        Invoke-RestMethod -Uri $WebhookUrl -Method Post -Body $body -ContentType 'application/json' -ErrorAction Stop
        Write-SysLog "Slack alert sent to $Channel"
        return $true
    } catch {
        Write-SysLog "Slack alert failed: $_" -Level 'ERROR'
        return $false
    }
}

public static object GetHttpEndpointStatus(string url, int timeoutSeconds = 10, int expectedStatusCode = 200) {
    var sw = System.Diagnostics.Stopwatch.StartNew();
    try {
        var request = System.Net.WebRequest.CreateHttp(url);
        request.Timeout = timeoutSeconds * 1000;
        request.Method = "HEAD";
        using (var response = (System.Net.HttpWebResponse)request.GetResponse()) {
            sw.Stop();
            return new { IsUp = (int)response.StatusCode == expectedStatusCode, StatusCode = (int)response.StatusCode, ResponseTimeMs = sw.ElapsedMilliseconds, Error = (string)null };
        }
    } catch (Exception ex) {
        sw.Stop();
        return new { IsUp = false, StatusCode = 0, ResponseTimeMs = sw.ElapsedMilliseconds, Error = ex.Message };
    }
}

function Generate-StrongPassword {
    param([int]$Length = 16, [switch]$IncludeSpecial)
    $chars = 'abcdefghkmnpqrstuvwxyzABCDEFGHKMNPQRSTUVWXYZ23456789'
    if ($IncludeSpecial) { $chars += '!@#$%&*?' }
    $password = -join ((1..$Length) | ForEach-Object { $chars[(Get-Random -Maximum $chars.Length)] })
    Write-SysLog "Password generated (length $Length)" -Level 'DEBUG'
    return $password
}

function Send-EmailHTML {
    param([string]$To, [string]$Subject, [string]$HtmlBody, [string[]]$Attachments = @(), [string]$Cc = '')
    $mailParams = @{
        SmtpServer = $SMTPServer
        From = 'noreply@corp.local'
        To = $To
        Subject = $Subject
        Body = $HtmlBody
        BodyAsHtml = $true
        Encoding = 'UTF8'
        ErrorAction = 'Stop'
    }
    if ($Cc) { $mailParams['Cc'] = $Cc }
    if ($Attachments.Count) { $mailParams['Attachments'] = $Attachments }
    try {
        Send-MailMessage @mailParams
        Write-SysLog "HTML email sent to $To"
        return $true
    } catch {
        Write-SysLog "Email failed: $_" -Level 'ERROR'
        return $false
    }
}

function Measure-ScriptPerformance {
    param([ScriptBlock]$ScriptBlock, [int]$Iterations = 1)
    $times = @()
    for ($i = 0; $i -lt $Iterations; $i++) {
        $sw = [System.Diagnostics.Stopwatch]::StartNew()
        & $ScriptBlock
        $sw.Stop()
        $times += $sw.Elapsed.TotalMilliseconds
    }
    return [PSCustomObject]@{
        TotalMs = [math]::Round($times | Measure-Object -Sum).Sum, 2
        AvgMs = [math]::Round(($times | Measure-Object -Average).Average, 2)
        MinMs = [math]::Round(($times | Measure-Object -Minimum).Minimum, 2)
        MaxMs = [math]::Round(($times | Measure-Object -Maximum).Maximum, 2)
        Iterations = $Iterations
    }
}

function Get-WeatherForecast {
    param([string]$City, [string]$ApiKey = $null, [string]$Units = 'metric')
    if (-not $ApiKey) { $ApiKey = Get-SecretFromVault -SecretName 'OpenWeatherApiKey' -VaultType 'Windows' }
    $url = "https://api.openweathermap.org/data/2.5/weather?q=$City&appid=$ApiKey&units=$Units"
    try {
        $data = Invoke-RestMethod -Uri $url -ErrorAction Stop
        return [PSCustomObject]@{
            City = $data.name
            Country = $data.sys.country
            Temperature = $data.main.temp
            FeelsLike = $data.main.feels_like
            Humidity = $data.main.humidity
            Description = $data.weather[0].description
            WindSpeed = $data.wind.speed
            Icon = $data.weather[0].icon
        }
    } catch {
        Write-SysLog "Weather API failed: $_" -Level 'ERROR'
        return $null
    }
}

function Repair-WindowsComponent {
    param([ValidateSet('DISM','SFC','Networking','PrintSpooler')][string]$Component, [string]$ComputerName = $env:COMPUTERNAME)
    $result = [PSCustomObject]@{ Component=$Component; Success=$false; Details='' }
    switch ($Component) {
        'DISM' {
            $output = Invoke-Command -ComputerName $ComputerName -ScriptBlock { dism /online /cleanup-image /restorehealth }
            $result.Success = $output -match 'operation completed successfully'
            $result.Details = $output
        }
        'SFC' {
            $output = Invoke-Command -ComputerName $ComputerName -ScriptBlock { sfc /scannow }
            $result.Success = $output -match 'did not find any integrity violations' -or $output -match 'repaired'
            $result.Details = $output
        }
        'Networking' {
            $cmds = @('ipconfig /release', 'ipconfig /renew', 'ipconfig /flushdns', 'netsh winsock reset')
            foreach ($cmd in $cmds) { Invoke-Command -ComputerName $ComputerName -ScriptBlock { param($c) cmd /c $c } -ArgumentList $cmd }
            $result.Success = $true
            $result.Details = 'Network stack reset'
        }
        'PrintSpooler' {
            Invoke-Command -ComputerName $ComputerName -ScriptBlock { Stop-Service Spooler; Start-Service Spooler }
            $result.Success = $true
            $result.Details = 'Print spooler restarted'
        }
    }
    Write-SysLog "Repair $Component on $ComputerName : $($result.Success)" -Level $(if($result.Success){'INFO'}else{'ERROR'})
    return $result
}

function Protect-String {
    param([string]$PlainText, [ValidateSet('DPAPI','AES')][string]$Method = 'DPAPI', [string]$Password = '')
    if ($Method -eq 'DPAPI') {
        $bytes = [System.Text.Encoding]::UTF8.GetBytes($PlainText)
        $encrypted = [System.Security.Cryptography.ProtectedData]::Protect($bytes, $null, [System.Security.Cryptography.DataProtectionScope]::CurrentUser)
        return [Convert]::ToBase64String($encrypted)
    } else {
        throw 'AES method requires implementation of key derivation'
    }
}

function Unprotect-String {
    param([string]$CipherText, [ValidateSet('DPAPI','AES')][string]$Method = 'DPAPI')
    if ($Method -eq 'DPAPI') {
        $bytes = [Convert]::FromBase64String($CipherText)
        $decrypted = [System.Security.Cryptography.ProtectedData]::Unprotect($bytes, $null, [System.Security.Cryptography.DataProtectionScope]::CurrentUser)
        return [System.Text.Encoding]::UTF8.GetString($decrypted)
    } else {
        throw 'AES method not implemented'
    }
}
